//! Identifiers.
//!
//! Public ids are UUIDs generated by the core through an injected factory.
//! Tenant/store/register/operator/product ids are **opaque** strings owned by
//! PI.COMMERCE Server: PI.Edge never interprets or mints them.

use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum IdError {
    #[error("`{0}` is not a valid UUID")]
    InvalidUuid(String),
    #[error("{0} must not be empty")]
    Empty(&'static str),
    #[error("{0} exceeds {1} characters")]
    TooLong(&'static str, usize),
}

macro_rules! uuid_id {
    ($(#[$doc:meta])* $name:ident) => {
        $(#[$doc])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
        #[serde(transparent)]
        pub struct $name(Uuid);

        impl $name {
            pub const fn from_uuid(id: Uuid) -> Self {
                Self(id)
            }

            pub const fn to_uuid(self) -> Uuid {
                self.0
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}", self.0)
            }
        }

        impl FromStr for $name {
            type Err = IdError;

            fn from_str(value: &str) -> Result<Self, Self::Err> {
                Uuid::parse_str(value)
                    .map(Self)
                    .map_err(|_| IdError::InvalidUuid(value.to_owned()))
            }
        }
    };
}

uuid_id!(
    /// Public id of a business day.
    BusinessDayId
);
uuid_id!(
    /// Public id of a register session.
    SessionId
);
uuid_id!(
    /// Public id of a retail transaction.
    TransactionId
);
uuid_id!(
    /// Public id of a transaction line.
    LineId
);
uuid_id!(
    /// Public id of a payment.
    PaymentId
);
uuid_id!(
    /// Public id of a journal or outbox event.
    EventId
);
uuid_id!(
    /// Local id of an imported catalog snapshot.
    ///
    /// Minted by PI.Edge because it identifies a *local import record*. The
    /// catalog content itself is identified upstream by `(version,
    /// content_hash)`; PI.Edge never mints product master ids.
    CatalogSnapshotId
);

/// Maximum length accepted for server-owned opaque identifiers.
pub const MAX_OPAQUE_ID_LEN: usize = 128;

macro_rules! opaque_id {
    ($(#[$doc:meta])* $name:ident) => {
        $(#[$doc])*
        #[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
        #[serde(transparent)]
        pub struct $name(String);

        impl $name {
            pub fn new(value: impl Into<String>) -> Result<Self, IdError> {
                let value = value.into();
                let trimmed = value.trim();
                if trimmed.is_empty() {
                    return Err(IdError::Empty(stringify!($name)));
                }
                if trimmed.chars().count() > MAX_OPAQUE_ID_LEN {
                    return Err(IdError::TooLong(stringify!($name), MAX_OPAQUE_ID_LEN));
                }
                Ok(Self(trimmed.to_owned()))
            }

            pub fn as_str(&self) -> &str {
                &self.0
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                f.write_str(&self.0)
            }
        }

        impl FromStr for $name {
            type Err = IdError;

            fn from_str(value: &str) -> Result<Self, Self::Err> {
                Self::new(value)
            }
        }
    };
}

opaque_id!(
    /// Tenant identifier, assigned by PI.COMMERCE Server.
    TenantId
);
opaque_id!(
    /// Store identifier, assigned by PI.COMMERCE Server.
    StoreId
);
opaque_id!(
    /// Physical register / terminal identifier.
    RegisterId
);
opaque_id!(
    /// Operator (cashier) identifier.
    OperatorId
);
opaque_id!(
    /// Canonical catalog reference. PI.Edge never creates products.
    ProductRef
);
opaque_id!(
    /// Reference to a price book, assigned upstream like every other piece of
    /// master data.
    PriceBookId
);

#[allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_and_renders_uuid_ids() {
        let raw = "11111111-2222-3333-4444-555555555555";
        let id: TransactionId = raw.parse().unwrap();
        assert_eq!(id.to_string(), raw);
        assert!("not-a-uuid".parse::<TransactionId>().is_err());
    }

    #[test]
    fn trims_and_validates_opaque_ids() {
        assert_eq!(StoreId::new("  STORE-01 ").unwrap().as_str(), "STORE-01");
        assert!(StoreId::new("   ").is_err());
        assert!(StoreId::new("x".repeat(MAX_OPAQUE_ID_LEN + 1)).is_err());
    }
}
